  'vcGoods_furniture': ['Furniture', 'फ़र्नीचर', 'Furniture', 'ಪೀಠೋಪಕರಣ', 'தளவாடங்கள்', 'ఫర్నిచర్', 'फर्निचर', 'ફર્નિચર', 'আসবাব', 'ਫਰਨੀਚਰ', 'فرنیچر', 'فرنیچر'],
